import {StyleSheet, TouchableOpacity, View} from 'react-native';
import {ReleaseReceipt} from '../../helper';
import {useTranslation} from 'react-i18next';
import {useNavigation} from '@react-navigation/native';
import TextCM from '../../../../../../../../components/Text';
import {CommonUtils, DateUtils} from '../../../../../../../../../utils';
import {Font} from '../../../../../../../../../constants';

type Props = {
  item: ReleaseReceipt;
};
const ExpandIssueReceipt = ({item}: Props) => {
  const navigation = useNavigation<any>();
  const {t} = useTranslation();

  const viewDocument = () => {
    navigation.navigate('ViewDocumentScreen', {
      item: item,
    });
  };
  return (
    <View style={styles.expandedDetails}>
      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>{t('BLDT.issue_receipt')}</TextCM>
        <TouchableOpacity style={{flex: 1}} onPress={viewDocument}>
          <TextCM
            style={[
              styles.detailValue,
              {textDecorationLine: 'underline', color: '#366AE2'},
            ]}>
            {item.fileName || '---'}
          </TextCM>
        </TouchableOpacity>
      </View>

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>{t('CM.format')}</TextCM>
        <View style={{flex: 1}}>
          <TextCM style={styles.detailValue}>
            {item?.fileName?.split('.')?.slice(-1)?.[0] || '---'}
          </TextCM>
        </View>
      </View>

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>{t('CM.size')}</TextCM>
        <View style={{flex: 1}}>
          <TextCM style={styles.detailValue}>
            {CommonUtils.getSize(item?.documentSize) || '---'}
          </TextCM>
        </View>
      </View>

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>{t('BLDT.release')}</TextCM>
        <View style={{flex: 1}}>
          <TextCM style={styles.detailValue}>
            {DateUtils.convertDateToDDMMYYYY_H_M(item.createdDate)}
          </TextCM>
        </View>
      </View>
    </View>
  );
};
export default ExpandIssueReceipt;

const styles = StyleSheet.create({
  expandedDetails: {
    backgroundColor: '#FFFFFF',
    borderRadius: 6,
    padding: 12,
    marginVertical: 8,
  },
  detailRow: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 8,
    columnGap: 12,
  },
  detailLabel: {
    fontSize: 12,
    fontFamily: Font.InterSemiBold600,
    color: '#00204D',
    width: 115,
  },
  detailValue: {
    fontSize: 12,
    fontFamily: Font.InterRegular400,
    color: '#00204DE5',
  },
  userInfo: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  avatar: {
    width: 24,
    height: 24,
    borderRadius: 12,
    marginRight: 8,
  },
  email: {
    fontSize: 12,
    color: '#6B7280',
  },
});
