import React, {useCallback, useState} from 'react';
import {
  FlatList,
  Keyboard,
  TouchableOpacity,
  TouchableWithoutFeedback,
  View,
} from 'react-native';
import {useTranslation} from 'react-i18next';
import {Icon, Input} from '@ui-kitten/components';
import {styles} from './styles';
import {useFocusEffect, useRoute} from '@react-navigation/native';
import useDebounce from '../../../hooks/useDebounce';
import {Color} from '../../../constants';
import TextCM from '../../components/Text';
import LoadingMore from '../../components/LoadingMore';
import HeaderCM from '../../components/Header/HeaderCM';
import ReceiptItem from './components/receipt-item';
import ModalFilter from './components/modal-filter';
import BottomSheetCM from '../../components/BottomSheet';
import {ValueFilterSearch} from './components/zustand/store';
import {SafeAreaView} from 'react-native-safe-area-context';
import {useQDTHAService} from '../../../hooks/apiHooks/useAPI';
import {Judgment} from '../interface/interface';
import {
  listStatusFromERequest,
  listType,
} from './components/modal-filter/helper';
import {useAppSelector} from '../../../hooks/useRedux';
import {DateUtils} from '../../../utils';
import {useConfigStore} from '../zustand/config';

const BA_QD_SCREEN = () => {
  const {t} = useTranslation();
  const route = useRoute<any>();
  const isReload = route?.params?.isReload || false;
  const type = (route?.params?.type as 'owner' | 'authorized') || 'owner';
  const [value, setValue] = useState('');
  const valueTextSearch = useDebounce(value, 300);
  const [visibleFilter, setVisibleFilter] = useState(false);

  const [listReceipt, setListReceipt] = useState<Judgment[]>([]);
  const [isRefreshing, setIsFreshing] = useState(false);
  const [isLoadMore, setIsLoadMore] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [page, setPage] = useState(0);
  const [totalPages, setTotalPages] = useState(0);

  const [valueFilterSearch, setValueFilterSearch] =
    useState<ValueFilterSearch>();

  const {dataAccount} = useAppSelector(state => state.account);

  const {LIST_ORG} = useConfigStore();

  const QDTHAService = useQDTHAService();

  useFocusEffect(
    useCallback(() => {
      getDataReceipt(0, false);
    }, [isReload, valueTextSearch, valueFilterSearch]),
  );
  const getDataReceipt = async (page: number, isLoadMore?: boolean) => {
    try {
      if (isLoadMore) {
        setIsLoadMore(true);
      } else {
        setIsLoading(true);
      }
      const params = {
        page: page,
        size: 20,
        sort: 'createdDate,desc',
        type: type,
      };
      const bodySearch: any = {
        q: valueTextSearch?.trim(),
        advanced: false,
        terms: {},
        multiRange: [{field: 'requestDate', gte: null, lte: null}],
      };
      if (type === 'authorized') {
        if (!valueFilterSearch?.orgIn) {
          bodySearch.orgIn = dataAccount?.orgIn || '/561/978';
        } else {
          bodySearch.orgIn = LIST_ORG[valueFilterSearch?.orgIn?.row]?.orgIn;
        }
      }
      if (valueFilterSearch?.status) {
        bodySearch.terms.status = valueFilterSearch?.status?.map(
          item => listStatusFromERequest[item.row].value,
        );
      }
      if (valueFilterSearch?.type) {
        bodySearch.terms.type = valueFilterSearch?.type?.map(
          item => listType[item.row].value,
        );
      }
      if (valueFilterSearch?.rangeDay?.startDate) {
        if (bodySearch?.multiRange?.[0]) {
          bodySearch.multiRange[0] = {
            ...bodySearch?.multiRange?.[0],
            gte: DateUtils.formatToIsoDate(
              valueFilterSearch?.rangeDay?.startDate.toISOString(),
              'start',
            ),
          };
        } else {
          bodySearch.multiRange = [];
          bodySearch.multiRange[0] = {
            field: 'requestDate',
            gte: DateUtils.formatToIsoDate(
              valueFilterSearch?.rangeDay?.startDate.toISOString(),
              'start',
            ),
            lte: null,
          };
        }
      }
      if (valueFilterSearch?.rangeDay?.endDate) {
        if (bodySearch?.multiRange?.[0]) {
          bodySearch.multiRange[0] = {
            ...bodySearch?.multiRange?.[0],
            lte: DateUtils.formatToIsoDate(
              valueFilterSearch?.rangeDay?.endDate.toISOString(),
              'end',
            ),
          };
        } else {
          bodySearch.multiRange = [];
          bodySearch.multiRange[0] = {
            field: 'requestDate',
            gte: null,
            lte: DateUtils.formatToIsoDate(
              valueFilterSearch?.rangeDay?.endDate.toISOString(),
              'end',
            ),
          };
        }
      }
      const res = await QDTHAService.getListJudgmentDecisions(
        params,
        bodySearch,
      );
      if (page === 0) {
        setListReceipt(res?.data);
        setTotalPages(res?.totalData || 0);
      } else {
        setListReceipt([...listReceipt, ...res?.data]);
      }
    } catch (error) {
    } finally {
      setIsLoading(false);
      setIsLoadMore(false);
      setIsFreshing(false);
    }
  };

  const handleSubmitFilter = () => {
    setVisibleFilter(false);
  };

  const onRefresh = () => {
    setIsFreshing(true);
    setPage(0);
    getDataReceipt(0, false);
  };

  const handleLoadMore = () => {
    if (page < Math.ceil(totalPages / 20)) {
      getDataReceipt(page + 1, true);
      setPage(page + 1);
    }
  };

  return (
    <TouchableWithoutFeedback onPress={() => Keyboard.dismiss()}>
      <SafeAreaView edges={['bottom']} style={styles.ctn}>
        <HeaderCM
          title={
            type === 'owner'
              ? t('Quyết định thi hành án của tôi')
              : 'Quyết định thi hành án trong đơn vị'
          }
          useLinearGradient={false}
          style={{backgroundColor: '#055FA4'}}
          contentStyle={{backgroundColor: '#055FA4'}}
        />
        <View style={styles.wrapInputSearch}>
          <Input
            allowFontScaling={false}
            style={styles.inputSearch}
            textStyle={{color: Color.Black}}
            placeholderTextColor={'#9FB0C7'}
            placeholder={t('CM.search')}
            value={value}
            status="basic"
            onChangeText={setValue}
            accessoryLeft={
              <TouchableOpacity onPress={() => false}>
                <Icon fill={'#9FB0C7'} name="search" />
              </TouchableOpacity>
            }
            accessoryRight={
              value ? (
                <TouchableOpacity onPress={() => setValue('')}>
                  <Icon name="close-outline" fill={Color.Black} />
                </TouchableOpacity>
              ) : undefined
            }
          />
          <TouchableOpacity
            onPress={() => setVisibleFilter(true)}
            style={styles.wrapFilterIcon}>
            <Icon
              fill={Color.White}
              name={'funnel-outline'}
              width={25}
              height={25}
            />
          </TouchableOpacity>
        </View>

        {!isLoading && (
          <FlatList
            showsVerticalScrollIndicator={false}
            data={listReceipt}
            keyExtractor={item => item?.id}
            renderItem={({item}) => <ReceiptItem receipt={item} />}
            onEndReachedThreshold={0.5}
            onRefresh={onRefresh}
            refreshing={isRefreshing}
            onEndReached={handleLoadMore}
            ListEmptyComponent={() => (
              <View
                style={{
                  alignItems: 'center',
                  justifyContent: 'center',
                  flex: 1,
                }}>
                <TextCM>{t('CM.emptyData')}</TextCM>
              </View>
            )}
            contentContainerStyle={{rowGap: 16, marginTop: 16}}
            ListFooterComponent={() => isLoadMore && <LoadingMore />}
          />
        )}

        <BottomSheetCM
          isVisible={visibleFilter}
          onClose={() => setVisibleFilter(false)}
          title={t('CM.filter')}
          renderContent={
            <ModalFilter
              handleSubmitFilter={handleSubmitFilter}
              onClose={() => setVisibleFilter(false)}
              setValueFilterSearch={setValueFilterSearch}
              valueFilterSearch={valueFilterSearch}
              type={type}
            />
          }
        />
      </SafeAreaView>
    </TouchableWithoutFeedback>
  );
};

export default BA_QD_SCREEN;
