import {
  ActivityIndicator,
  RefreshControl,
  ScrollView,
  View,
} from 'react-native';
import {listActionNext, statusRequestTagProperties} from './helper';
import {useEffect, useState} from 'react';
import {useRoute} from '@react-navigation/native';
import Toast from 'react-native-toast-message';
import {useTranslation} from 'react-i18next';
import {styles} from './styles';
import TextCM from '../../../../components/Text';
import HeaderCM from '../../../../components/Header/HeaderCM';
import {Color} from '../../../../../constants';
import DetailItem from '../../../../screen/detail-receipt/component/detail-item';
import {
  IconIdReceipt,
  IconCalendarLabel,
  IconPersonlabel,
  IconLabelReceiptStatus,
  IconLabelKey,
} from '../../../../../assets/images';
import {DateUtils} from '../../../../../utils';
import {listStatusReceipt} from '../modal-filter/helper';
import BottomItem from '../bottom-item';
import {IJudgmentDetail} from '../../../interface/interface';
import {useAccountInfoServices} from '../../../../../hooks/apiHooks/useAccountInfoServices';
import {useQDTHAService} from '../../../../../hooks/apiHooks/useAPI';
import {IUserInfo} from '../../../../../model/interface/service.interface';
import {useConfigStore} from '../../../zustand/config';

const BA_QDDetailScreen = () => {
  const AccountService = useAccountInfoServices();
  const QDTHAService = useQDTHAService();
  const {t} = useTranslation();
  const router = useRoute<any>();
  const {id} = router.params;
  const [dataDetailReceipt, setDetailReceipt] = useState<IJudgmentDetail>(
    {} as any,
  );
  const [createByDetail, setCreateByDetail] = useState<IUserInfo>();
  const [isLoading, setIsLoading] = useState(false);
  const [refreshing, setRefresing] = useState(false);

  const {LIST_APPLICATION_STATUS} = useConfigStore();

  const getDataDetail = async (isLoading: boolean) => {
    if (isLoading) {
      setIsLoading(true);
    } else {
      setRefresing(true);
    }
    try {
      const res = (await QDTHAService.judgmentDecisionDetail(
        id,
      )) as IJudgmentDetail;
      if (res) {
        setDetailReceipt(res);
        const filter = {
          logins: [res.createdBy],
        };
        const resCreateBy = await AccountService.getListAccount(filter);
        setCreateByDetail(resCreateBy?.data[0]);
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.error'),
        });
      }
    } catch (error) {
      console.error(error);
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    } finally {
      setIsLoading(false);
      setRefresing(false);
    }
  };
  useEffect(() => {
    getDataDetail(true);
  }, [id]);

  const StatusTag = ({
    status,
    type,
  }: {
    status: string;
    type: 'DEFAULT' | 'REQUEST' | 'MIX';
  }) => {
    let properties;
    if (type === 'DEFAULT') {
      properties = LIST_APPLICATION_STATUS.find(
        (item: any) => item.value === status,
      );
    } else if (type === 'REQUEST') {
      properties = statusRequestTagProperties.find(
        (item: any) => item?.value?.toLowerCase() === status,
      );
    } else {
    }
    if (properties) {
      return (
        <View style={{flex: 1, flexDirection: 'row'}}>
          <View
            style={[
              styles.statusTag,
              {backgroundColor: properties?.bgColor || '#EF5DA81A'},
            ]}>
            <TextCM
              style={[
                styles.statusText,
                {color: properties?.color || '#d94936'},
              ]}>
              {t(`${properties?.label}`)}
            </TextCM>
          </View>
          <View style={{flex: 1}} />
        </View>
      );
    }
    return (
      <View style={{flexDirection: 'row', flex: 1}}>
        <View style={[styles.statusTag, {backgroundColor: '#EF5DA81A'}]}>
          <TextCM style={[styles.statusText, {color: '#d94936'}]}>
            {t(`BLDT.${status}`)}
          </TextCM>
        </View>
        <View style={{flex: 1}} />
      </View>
    );
  };

  const onRefresh = () => {
    setRefresing(true);
    getDataDetail(false);
  };

  return (
    <>
      <HeaderCM
        listColor={['#072A7E', '#00CEF3']}
        title={t('Chi tiết yêu cầu')}
      />
      {isLoading ? (
        <View style={{flex: 1, justifyContent: 'center', alignItems: 'center'}}>
          <ActivityIndicator color={Color.BgPrimary} size={'large'} />
        </View>
      ) : (
        <ScrollView
          refreshControl={
            <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
          }
          style={styles.content}>
          <View style={styles.titleSection}>
            <TextCM style={styles.titleText}>
              {dataDetailReceipt?.attrs?.name || '---'}
            </TextCM>
            <TextCM style={styles.idText}>
              {dataDetailReceipt?.requestCode || '---'}
            </TextCM>
          </View>

          <View style={styles.detailsSection}>
            <DetailItem
              icon={<IconCalendarLabel width={16} height={16} />}
              label={t('CM.createDateCard')}
              value={DateUtils.convertDateToDDMMYYYY_H_M(
                dataDetailReceipt?.createdDate,
              )}
            />

            <DetailItem
              icon={<IconPersonlabel width={16} height={16} />}
              label={t('CM.createdBy')}
              isUser={true}
              value={{
                name: createByDetail?.personalName || '---',
                email: createByDetail?.email || '---',
                avatar: createByDetail?.avatar || '',
              }}
            />

            <DetailItem
              icon={<IconLabelReceiptStatus width={16} height={16} />}
              label={t('BLDT.flow_status')}
              value={
                <StatusTag
                  status={dataDetailReceipt?.attrs?.requestStatus}
                  type="DEFAULT"
                />
              }
            />

            <DetailItem
              icon={<IconLabelKey width={16} height={16} />}
              label={t('BLDT.receipt_status')}
              value={
                <StatusTag status={dataDetailReceipt?.status} type="REQUEST" />
              }
            />

            <View style={styles.bottomMenu}>
              {listActionNext.map(item => {
                return (
                  <BottomItem
                    key={item.key}
                    action={item.key}
                    icon={item.icon}
                    label={item.label}
                    id={id}
                    dataDetailReceipt={dataDetailReceipt}
                  />
                );
              })}
            </View>
          </View>
        </ScrollView>
      )}
    </>
  );
};

export default BA_QDDetailScreen;
